        if(!game.canPlay(card)){reject(cardView);Toast.makeText(this,"请选择同色、同点数或可用的万能牌",Toast.LENGTH_SHORT).show();return;}
        if(card.color>=0){launchCard(cardView,()->submitPlay(index,0));return;}
        final int expected=lan==null?-1:lan.revision;LinearLayout choices=column();choices.setPadding(d(20),d(8),d(20),d(8));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("下一轮，选一种颜色").setView(choices).setNegativeButton("取消",null).create();
